import{prepare,ready}from'./browser.js';import{accountFixture,accountOwner}from'./account.js';import{commerceFixture}from'./commerce.js';import{report}from'./order-pdf.js';
export const owner=accountOwner,portfolio='00000000-0000-4000-8000-000000000000';
export async function setupLinks(page,{records,plan='pro',seedSettings={visitSettings:{workingDays:[1,2,3,4,5]},frequencies:{},untouched:'preserved'}}={}){
 await prepare(page,{records,lockAuthFixture:true});await accountFixture(page,{plan,photo:false});await commerceFixture(page);
 await page.addInitScript(({owner,portfolio,seedSettings})=>{if(!localStorage.getItem('traxio_sync_owner_v29'))localStorage.setItem('traxio_sync_owner_v29',owner);const key='__links_cloud';if(!localStorage.getItem(key))localStorage.setItem(key,JSON.stringify([{id:'90000000-0000-4000-8000-000000000001',user_id:owner,portfolio_id:portfolio,kind:'settings',data:seedSettings,revision:1,deleted:false}]));window.__linksWrites=[];const base=window.supabase.createClient;window.supabase.createClient=(...args)=>{const c=base(...args),from=c.from.bind(c),rpc=c.rpc.bind(c);const load=()=>JSON.parse(localStorage.getItem(key)||'[]');c.from=table=>{if(table!=='traxelo_workspace_items')return from(table);let filters={},start=0,end=499;const q={select:()=>q,eq:(k,v)=>{filters[k]=v;return q;},order:()=>q,range:(a,b)=>{start=a;end=b;return q;},then:yes=>Promise.resolve({data:load().filter(r=>Object.entries(filters).every(([k,v])=>r[k]===v)).slice(start,end+1),error:null}).then(yes)};return q;};c.rpc=async(name,p)=>{if(name!=='traxelo_write_owned_item')return rpc(name,p);if(window.__linksFail)return{error:{message:'Falha de salvamento simulada'}};const who=(await c.auth.getUser()).data?.user?.id,current=window.RotaMapaPortfolioScope.loadedId;if(p.p_owner!==who||who!==owner)return{error:{message:'Conta incorreta'}};const all=load(),old=all.find(r=>r.user_id===who&&r.portfolio_id===current&&r.id===p.p_id);if((old?.revision||0)!==p.p_revision)return{error:{code:'40001',message:'Configuração mudou em outro aparelho'}};const row={id:p.p_id,user_id:who,portfolio_id:current,kind:p.p_kind,data:structuredClone(p.p_data),revision:(old?.revision||0)+1,deleted:!!p.p_deleted};if(window.__linksHold)await new Promise(resolve=>window.__linksRelease=resolve);localStorage.setItem(key,JSON.stringify([...all.filter(r=>!(r.user_id===who&&r.id===row.id)),row]));window.__linksWrites.push(structuredClone(row));return{data:row,error:null};};return c;};
 },{owner,portfolio,seedSettings});
 if(process.env.TRAXELO_PWA_BASE)await page.route(process.env.TRAXELO_PWA_BASE+'/**',route=>route.continue());
 await ready(page);await page.waitForFunction(()=>window.TraxeloWorkspace?.getStore()?.items('settings').length===1);await page.waitForFunction(()=>window.RotaMapaSales?.getStore()?.events().some(e=>e.kind==='product'));return{owner,portfolio};
}
export async function identifyEMS(page){await page.locator('[data-tab=links]').click();await page.locator('#usefulCompanyOpen').click();await page.locator('#usefulCompanyChoice').selectOption('ems');await page.locator('#usefulCompanySave').click();await page.locator('#usefulCompanyDialog').waitFor({state:'hidden'});}
export async function seedPending(page){await page.evaluate(text=>{const p=RotaMapaSales.getStore().events().find(p=>p.kind==='product'),receipt={...RotaMapaOrderPdfModel.parseText(text),sha256:'a'.repeat(64),fileName:'pending.pdf',distributor:'Acripel'},source=RotaMapaOrderPdfModel.combine([receipt]),sale={id:'20000000-0000-4000-8000-000000000009',kind:'sale',clientId:String(clients[0].id),clientName:'Farmácia do pedido',status:'confirmed',date:TraxeloVisitsModel.day(),registeredAt:new Date().toISOString(),recordedAt:new Date().toISOString(),source,lines:receipt.items.map((i,index)=>RotaMapaOrderPdfModel.line(p,i,0,index,receipt)),totalCents:receipt.totalCents};RotaMapaSales.getStore().add(sale);RotaMapaSales.refresh();},report({status:'PEDIDO EM PROCESSAMENTO'}));await page.locator('#billingReminder').click();await page.locator('[data-billing-market]').waitFor();}
export async function mockClipboard(page,{copied=true,popup=true,native=false}={}){await page.evaluate(({copied,popup,native})=>{window.__copied=[];window.__external=[];window.__blankClosed=false;Object.defineProperty(navigator,'clipboard',{configurable:true,value:{writeText:async text=>{if(!copied)throw Error('Clipboard blocked');window.__copied.push(text);}}});document.execCommand=()=>false;if(native){window.Capacitor={isNativePlatform:()=>true,registerPlugin:name=>({openUrl:async({url})=>{window.__external.push({name,url});return{completed:true};},open:async({url})=>{window.__external.push({name,url});}})};}else{window.open=()=>popup?{closed:false,opener:null,location:{replace:url=>window.__external.push({name:'browser',url})},close:()=>window.__blankClosed=true}:null;}},{copied,popup,native});}
